    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1zc3r65elb', 'course-bili-bv1zc3r65elb', '100001', '0', 'BILI-DATA-S7N6R7', 'course-category-data', 'instructor-bili-279748367', 'Michael Porinchak老师的AP统计学课程视频(2026课程改革后)', '60 讲完整课程 · 34 小时 8 分钟', 'Michael Porinchak老师的AP统计学课程视频(2026课程改革后)。共 60 讲，累计 34.1 小时，由 归隐破戒的流数术之魂 讲解，章节结构完整，可直接在课程播放器中观看。', '针对2026年AP统计课程和考试改革后的版本。也就对应了2027届及以后的考试版本 很抱歉，没有AP官方视频了，美国大学理事会（CB）取消了计划 课程结构：共 8 章 60 讲，累计时长 34 小时 8 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握 Excel、SQL 与 Python 三件套的数据处理能力","独立完成数据清洗、建模、可视化与结论输出","理解指标体系与业务分析方法，能撰写可落地的分析报告","具备数据分析师岗位求职所需的项目与作品"]', '["零基础转行数据分析的职场人","需要提升数据能力的运营、产品与市场人员","在校学生与应届生"]', '["熟悉电脑基本操作","无需编程基础，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/e4426109421561d985f5b52a38bd95489461a62f.jpg', '["数据分析","Excel","SQL","Michael","2026课程改革后"]', 122909, 60, 740, '4.5', 183, 'BV1zC3r65ELB', NULL, NULL, NULL, 1, 0, 'standard', NULL, '归隐破戒的流数术之魂', 0, 'tenant', 'published', '2026-07-29T03:20:47.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
