INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1azjx65egp', 'course-bili-bv1azjx65egp', '100001', '0', 'BILI-DATA-44HNE4', 'course-category-data', 'instructor-bili-542307689', '苏黎世联邦理工学院 数据建模与数据库 中英字幕 1080P', '23 讲完整课程 · 35 小时 16 分钟', '苏黎世联邦理工学院 数据建模与数据库 课程整体结构与目标 课程从实际科学数据管理案例（如阿波罗登月样本数据库）引入动机，随后深入关系模型理论、SQL查询语言、概念与逻辑建模、规范化理论，最后讲解数据库管理系统（DBMS）', '课程简介：苏黎世联邦理工学院 数据建模与数据库 课程整体结构与目标 课程从实际科学数据管理案例（如阿波罗登月样本数据库）引入动机，随后深入关系模型理论、SQL查询语言、概念与逻辑建模、规范化理论，最后讲解数据库管理系统（DBMS）的内部架构（存储、查询执行、事务、恢复等）。理论、实践和系统实现并重，包含SQL上手实验、期中复习等内容。核心知识模块： 1. 关系模型与关系代数/演算 数据库理论基础，包括关系（表）的定义、键的概念、关系代数操作（选择、投影、连接、并、交、差等）以及关系演算，为后续所有查询和设计提供形式化基础。2. SQL查询语言（核心 + 高级特性） SQL的实际使用，包括基本查询、连接、聚合、子查询、NULL与三值逻辑、视图（View）、递归查询（WITH RECURSIVE）等。课程强调动手实践能力。3. 概念建模与逻辑设计 实体-关系（ER）模型的建模方法，以及如何将ER模型转换为关系模式（Logical Modeling），是数据建模的核心技能。4. 完整性约束与函数依赖 各种约束机制（主键、外键、CHECK等）和函数依赖（Functional Dependency）理论，用于保证数据一致性和指导模式设计。5. 数据库规范化理论 从1NF到BCNF、4NF、5NF的规范化过程，解决数据冗余、插入/删除/更新异常等问题，是关系数据库设计的核心理论。6. DBM 课程结构：共 3 章 23 讲，累计时长 35 小时 16 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握 Excel、SQL 与 Python 三件套的数据处理能力","独立完成数据清洗、建模、可视化与结论输出","理解指标体系与业务分析方法，能撰写可落地的分析报告","具备数据分析师岗位求职所需的项目与作品"]', '["零基础转行数据分析的职场人","需要提升数据能力的运营、产品与市场人员","在校学生与应届生"]', '["熟悉电脑基本操作","无需编程基础，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/14af6b83dc7bf4f71302a87184d26272bfe88603.jpg', '["数据分析","Excel","SQL","全集","苏黎世联邦理工学院","数据建模与数据库"]', 127008, 23, 252, '4.7', 147, 'BV1azjX65EGp', '129.00', '206.40', 'CNY', 0, 0, 'standard', NULL, '码农的洋墨水', 0, 'tenant', 'published', '2026-06-25T05:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
