INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1dz4y1w7kw', 'course-bili-bv1dz4y1w7kw', '100001', '0', 'BILI-DATA-0S12MQ', 'course-category-data', 'instructor-bili-297175934', 'Hive实操入门', '39 讲完整课程 · 5 小时 47 分钟', '黑马 hive是基于Hadoop的一个数据仓库工具，用来进行数据提取、转化、加载，这是一种可以存储、查询和分析存储在Hadoop中的大规模数据的机制。hive数据仓库工具能将结构化的数据文件映射为一张数据库表，', '课程简介：黑马 hive是基于Hadoop的一个数据仓库工具，用来进行数据提取、转化、加载，这是一种可以存储、查询和分析存储在Hadoop中的大规模数据的机制。hive数据仓库工具能将结构化的数据文件映射为一张数据库表，并提供SQL查询功能，能将SQL语句转变成MapReduce任务来执行。Hive的优点是学习成本低，可以通过类似SQL语句实现快速MapReduce统计，使MapReduce变得更加简单，而不必开发专门的MapReduce应用程序。课程结构：共 5 章 39 讲，累计时长 5 小时 47 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握 Excel、SQL 与 Python 三件套的数据处理能力","独立完成数据清洗、建模、可视化与结论输出","理解指标体系与业务分析方法，能撰写可落地的分析报告","具备数据分析师岗位求职所需的项目与作品"]', '["零基础转行数据分析的职场人","需要提升数据能力的运营、产品与市场人员","在校学生与应届生"]', '["熟悉电脑基本操作","无需编程基础，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/a271f980bec48960bb740713e5a3e5b29f5df9b6.png', '["数据分析","Excel","SQL","Hive实操入门"]', 20876, 39, 1533, '4.3', 285, 'BV1dZ4y1w7kw', NULL, NULL, NULL, 1, 0, 'standard', NULL, '是番茄火锅呀', 0, 'tenant', 'published', '2021-03-30T07:57:06.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
