    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-2045520', 'course-bili-season-2045520', '100001', '0', 'BILI-DATA-H1D38H', 'course-category-data', 'instructor-bili-1111135013', '02-1-Numpy基础教程', '49 讲完整课程 · 15 小时 10 分钟', 'NumPy 简介 NumPy（Numerical Python）是 Python 生态系统中非常重要的科学计算基础库。它为我们提供了多维数组（ndarray）这种核心数据结构，以及一系列高效的向量化运算方法。利用 Num', '课程简介：NumPy 简介 NumPy（Numerical Python）是 Python 生态系统中非常重要的科学计算基础库。它为我们提供了多维数组（ndarray）这种核心数据结构，以及一系列高效的向量化运算方法。利用 NumPy，我们可以对大量数据进行快速的数值计算，并为后续的数据分析或机器学习打下坚实基础。课程结构：共 1 章 49 讲，累计时长 15 小时 10 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握 Excel、SQL 与 Python 三件套的数据处理能力","独立完成数据清洗、建模、可视化与结论输出","理解指标体系与业务分析方法，能撰写可落地的分析报告","具备数据分析师岗位求职所需的项目与作品"]', '["零基础转行数据分析的职场人","需要提升数据能力的运营、产品与市场人员","在校学生与应届生"]', '["熟悉电脑基本操作","无需编程基础，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/6d8280e27c67172a94d9fb26c0f648daeffb281c.jpg', '["数据分析","Excel","SQL","Numpy基础教程"]', 54646, 49, 1049, '4.5', 255, 'BV1duPvetEnH', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'stanfordbshan', 0, 'tenant', 'published', '2025-02-25T09:04:58.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
